const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
fs.writeFileSync("/w/t.mjs", `
import { generateText } from "ai";
const model = {
  specificationVersion: "v3", provider: "mock", modelId: "mock-model", supportedUrls: {},
  doGenerate: async () => ({
    content: [{ type: "text", text: "hi" }],
    finishReason: { unified: "stop", raw: "stop" },
    usage: { inputTokens: { total: 1, noCache: 1, cacheRead: 0, cacheWrite: 0 }, outputTokens: { total: 1, text: 1, reasoning: 0 } },
    warnings: [],
    request: { body: "REQ_BODY" },
    response: { id: "r1", timestamp: new Date(0), modelId: "mock-model", body: "RES_BODY" },
  }),
  doStream: async () => { throw new Error("no stream"); },
};
const result = await generateText({ model, prompt: "hello" });
export default { text: result.text, req: result.request.body, res: result.response.body };
`);
import("/w/t.mjs").then(({ default: r }) => {
  if (r.text !== "hi") broken("generateText returned text " + JSON.stringify(r.text));
  if (r.req === "REQ_BODY" && r.res === "RES_BODY") symptom("generateText result keeps request.body and response.body by default");
  if (r.req !== undefined || r.res !== undefined) broken("unexpected request.body " + JSON.stringify(r.req) + " / response.body " + JSON.stringify(r.res));
  console.log("OK: generateText result has no request.body or response.body by default");
}, (e) => broken("generateText threw: " + (e && e.message)));

